    /// ساخت خلاصهٔ مارک‌داون از درخت JSON — محتوای زبانهٔ «متن» نقشهٔ نمونه
    static func markdown(from json: String) -> String {
        guard let data = json.data(using: .utf8),
              let obj = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
              let root = obj["root"] as? [String: Any] else { return "" }
        var lines: [String] = []
        func walk(_ node: [String: Any], _ depth: Int) {
            let text = (node["text"] as? String) ?? ""
            if depth == 0 {
                lines.append("# \(text)")
            } else {
                lines.append(String(repeating: "  ", count: depth - 1) + "- " + text)
            }
            for child in (node["children"] as? [[String: Any]]) ?? [] {
                walk(child, depth + 1)
            }
        }
        walk(root, 0)
        return lines.joined(separator: "\n")
    }
